SELECT id, occurred_at, actor_login_id, actor_name, action_code, target_type, target_id,
       result_code, trace_id, request_id, changed_fields
FROM ifj_operation_audit WHERE id = #{id}

SELECT id, occurred_at, actor_login_id, actor_name, action_code, target_type, target_id,
       result_code, trace_id, request_id, changed_fields
FROM ifj_operation_audit
WHERE occurred_at >= #{from} AND occurred_at <= #{to}
AND actor_login_id = #{actorLoginId}
AND action_code = #{actionCode}
AND target_type = #{targetType}
AND target_id = #{targetId}
AND result_code = #{resultCode}

    ORDER BY occurred_at ASC, id ASC
    ORDER BY occurred_at DESC, id DESC
